#include <string>
#include <vector>

class Solution {
public:
    int numberOfSubstrings(std::string s, int k) {
        int counts[26] = {0};
        int left = 0;
        int ans = 0;
        int n = s.size();

        for (int right = 0; right < n; ++right) {
            counts[s[right] - 'a']++;
            while (counts[s[right] - 'a'] >= k) {
                ans += n - right;
                counts[s[left] - 'a']--;
                left++;
            }
        }
        return ans;
    }
};

class Solution {
    public int numberOfSubstrings(String s, int k) {
        int[] counts = new int[26];
        int left = 0;
        int ans = 0;
        int n = s.length();

        for (int right = 0; right < n; right++) {
            counts[s.charAt(right) - 'a']++;
            while (counts[s.charAt(right) - 'a'] >= k) {
                ans += n - right;
                counts[s.charAt(left) - 'a']--;
                left++;
            }
        }
        return ans;
    }
}

var numberOfSubstrings = function(s, k) {
    const counts = new Int32Array(26);
    let left = 0;
